ALLOWED_TAGS = ['b', 'i', 'u', 'a']

SECRET_KEY = b'supersecretkey'


def sanitize_html(input_html):
    sanitized_dict = {}
    for tag in ALLOWED_TAGS:
        pattern = r'<%s.*?>.*?</%s>' % (tag, tag)
        matches = re.findall(pattern, input_html)
        if tag not in sanitized_dict:
            sanitized_dict[tag] = matches
        else:
            sanitized_dict[tag] += matches
    return sanitized_dict


def verify_signature(data, signature):
    computed_signature = hmac.new(SECRET_KEY, data.encode(), 'sha256').hexdigest()
    if hmac.compare_digest(computed_signature, signature):
        return True
    return False

