class DatabaseArchiver:
    def __init__(self, db_connection):
        self.db_connection = db_connection

    def get_old_records(self):
        for record in self.db_connection.query("SELECT * FROM records WHERE age > 365"):
            yield record

    def archive_records(self):
        for record in self.get_old_records():
            archive_key = self.compute_archive_key(record)
            if archive_key in self.db_connection.archives:
                self.db_connection.archives[archive_key].append(record)
            else:
                self.db_connection.archives[archive_key] = [record]

    def compute_archive_key(self, record):
        # Simulate expensive computation
        time.sleep(0.1)
        return "archive_%s" % record['id']

