def reconcile_transactions(transactions, balance_sheet):
    daily_sums = {}
    for date, amount in transactions:
        if date in daily_sums:
            daily_sums[date] += amount
        else:
            daily_sums[date] = amount
    for date, total in daily_sums.items():
        if date in balance_sheet:
            balance_sheet[date] += total
        else:
            balance_sheet[date] = total

    for date, balance in balance_sheet.items():
        yield "On %s, the balance was %s" % (date, balance)

