def lazy_load_tree(root):
    import os
    stack = [(root, 0)]
    while stack:
        current_path, level = stack.pop()
        if os.path.isdir(current_path):
            try:
                entries = os.listdir(current_path)
                for entry in entries:
                    path = os.path.join(current_path, entry)
                    stack.append((path, level + 1))
            except Exception as e:
                print("Error accessing directory %s: %s" % (current_path, e))
        else:
            yield current_path

